  const visual = input.form ? input.form : photo ? `<figure class="hero-photo${shape ? ` ${shape}` : ""}"><img src="${t(photo)}" alt="${t(input.photoAlt)}" width="${width}" height="${height}" fetchpriority="high" decoding="async">${caption}</figure>` : `<div class="object${layout.hero === "cover" ? " big" : ""}">${monogram}${input.object}</div>`;
