    products: () => `<section class="${BAND}" id="mon"><div class="wrap"><h2>${one ? "Ch\u1ECDn g\xF3i c\u1EE7a b\u1EA1n" : "Ch\u1ECDn m\xF3n"}</h2>${cards}</div></section>`,
    proof: () => proofSection(context),
