  return shell({ type: "catalog", title: page3.headline, description: page3.introduction, look: context.look, brand: context.brand, settings: context.settings, slug: context.funnel.slug, preview: context.preview, index: true, bar: false, zalo: true, status: context.open ? "" : "trang \u0111ang t\u1EA1m d\u1EEBng", body, script });
