var channels = ["Facebook", "TikTok", "Shopee", "Zalo", "C\u1EEDa h\xE0ng", "Ch\u01B0a b\xE1n"];
var experiences = ["Ch\u01B0a t\u1EEBng b\xE1n", "D\u01B0\u1EDBi 1 n\u0103m", "Tr\xEAn 1 n\u0103m"];
function renderRecruit(context, page3) {
  const brief = context.funnel.brief;
  if (brief.kind !== "recruit") throw new Error("Not a recruit funnel");
  const ctv = brief.roles.includes("ctv");
  const agent = brief.roles.includes("agent");
  const chips = [
    ...ctv && brief.ctvCommission ? [{ text: `C\u1ED9ng t\xE1c vi\xEAn: ${brief.ctvCommission}`, icon: "tag" }] : [],
    ...agent && brief.agentDiscount ? [{ text: `\u0110\u1EA1i l\xFD: ${brief.agentDiscount}`, icon: "tag" }] : [],
    { text: "Kh\xF4ng thu ph\xED tham gia", icon: "shield" }
  ];
  const card = (title, lines, foot) => `<div class="role-card"><h3>${t(title)}</h3>${rows(lines)}${foot ? `<p class="muted">${t(foot)}</p>` : ""}</div>`;
  const ways = [
    ctv ? card("C\u1ED9ng t\xE1c vi\xEAn", [["Hoa h\u1ED3ng", brief.ctvCommission ?? ""], ["Tr\u1EA3 hoa h\u1ED3ng", brief.ctvPayday ?? ""], ["Giao h\xE0ng", brief.ctvShipping === "self" ? "B\u1EA1n t\u1EF1 giao cho kh\xE1ch" : "Shop \u0111\xF3ng g\xF3i v\xE0 giao cho kh\xE1ch"]], brief.ctvShipping === "self" ? "" : "Kh\xF4ng c\u1EA7n nh\u1EADp h\xE0ng tr\u01B0\u1EDBc.") : "",
    agent ? card("\u0110\u1EA1i l\xFD / s\u1EC9", [["\u0110\u01A1n nh\u1EADp \u0111\u1EA7u", brief.agentFirstOrder ?? ""], ["Chi\u1EBFt kh\u1EA5u", brief.agentDiscount ?? ""], ["Gi\xE1 b\xE1n", brief.agentKeepPrice ? "B\xE1n \u0111\xFAng gi\xE1 shop ni\xEAm y\u1EBFt" : ""]], "") : ""
  ].filter(Boolean).join("");
  const policy = `<div class="product policy-card"><span class="pill">${t(page3.eyebrow)}</span><strong class="product-name">${t(brief.productLine)}</strong><ul>${chips.slice(0, -1).map((chip) => `<li>${icon("check", 16)}<span>${t(chip.text)}</span></li>`).join("")}<li>${icon("shield", 16)}<span>Kh\xF4ng thu ph\xED tham gia, kh\xF4ng \u0111\u1EB7t c\u1ECDc</span></li></ul></div>`;
  const roleChoices = [...ctv ? [["ctv", "C\u1ED9ng t\xE1c vi\xEAn"]] : [], ...agent ? [["agent", "\u0110\u1EA1i l\xFD / s\u1EC9"]] : [], ["unsure", "Ch\u01B0a r\xF5, c\u1EA7n t\u01B0 v\u1EA5n"]];
  const extra = `<fieldset class="fieldset"><legend class="field-legend">B\u1EA1n mu\u1ED1n l\xE0m</legend><div class="choice">${roleChoices.map(([value, label], index) => `<label><input type="radio" name="role" value="${value}"${index === 0 ? " checked" : ""}><span>${t(label)}</span></label>`).join("")}</div></fieldset>
<label class="field"><span>T\u1EC9nh / th\xE0nh b\u1EA1n \u1EDF</span><select name="province" required><option value="">Ch\u1ECDn t\u1EC9nh, th\xE0nh</option>${provinces.map((name) => `<option>${t(name)}</option>`).join("")}</select></label>
<fieldset class="fieldset"><legend class="field-legend">B\u1EA1n \u0111ang b\xE1n \u1EDF \u0111\xE2u <small>(kh\xF4ng b\u1EAFt bu\u1ED9c)</small></legend><div class="choice">${channels.map((name) => `<label><input type="checkbox" name="channels" value="${t(name)}"><span>${t(name)}</span></label>`).join("")}</div></fieldset>
<fieldset class="fieldset"><legend class="field-legend">Kinh nghi\u1EC7m b\xE1n h\xE0ng <small>(kh\xF4ng b\u1EAFt bu\u1ED9c)</small></legend><div class="choice">${experiences.map((name) => `<label><input type="radio" name="experience" value="${t(name)}"><span>${t(name)}</span></label>`).join("")}</div></fieldset>`;
  const form = leadForm({ id: "lead-form", title: page3.formTitle, description: page3.formDescription, cta: page3.cta, reassurance: page3.reassurance, consent: page3.consent, noteLabel: "B\u1EA1n mu\u1ED1n h\u1ECFi g\xEC", offerName: "ch\u01B0\u01A1ng tr\xECnh c\u1ED9ng t\xE1c", open: context.open, extra, email: false, privacy: privacyUrl(context.funnel.slug) });
  const identity = [context.brand.name, brief.area ? `\u0110ang t\xECm \u1EDF: ${brief.area}` : ""].filter(Boolean).join(" \xB7 ");
  const body = layoutBody(context, {
    hero: () => hero(context, { eyebrow: page3.eyebrow, title: page3.headline, highlight: page3.highlight, lead: page3.introduction, chips, object: policy, photoAlt: brief.productLine, cta: context.open ? anchorButton(page3.cta, "#dang-ky") : "", variant: `recruit-${styleOf(context.look.layout)}` }),
    why: () => `<section class="${BAND}"><div class="wrap"><h2>${t(page3.whyTitle)}</h2>${benefitList(context, page3.why)}</div></section>`,
    ways: () => ways ? `<section class="${BAND}"><div class="wrap"><h2>${ctv && agent ? "Ch\u1ECDn c\xE1ch h\u1EE3p t\xE1c" : "Quy\u1EC1n l\u1EE3i"}</h2><div class="role-cards">${ways}</div></div></section>` : "",
    terms: () => brief.tiers?.length ? `<section class="${BAND}"><div class="narrow"><h2>Chi\u1EBFt kh\u1EA5u theo m\u1EE9c</h2><table class="tiers"><thead><tr><th>M\u1EE9c</th><th>Chi\u1EBFt kh\u1EA5u / hoa h\u1ED3ng</th></tr></thead><tbody>${brief.tiers.map((tier) => `<tr><td>${t(tier.condition)}</td><td>${t(tier.rate)}</td></tr>`).join("")}</tbody></table></div></section>` : "",
    support: () => brief.supports?.length ? `<section class="${BAND}"><div class="narrow"><h2>Shop h\u1ED7 tr\u1EE3</h2>${ticks2(brief.supports)}</div></section>` : "",
    requirements: () => `<section class="${BAND}"><div class="narrow"><h2>Y\xEAu c\u1EA7u</h2>${ticks2([...brief.requirements ?? [], "Kh\xF4ng thu ph\xED tham gia, kh\xF4ng \u0111\u1EB7t c\u1ECDc"])}</div></section>`,
    steps: () => `<section class="${BAND}"><div class="wrap"><h2>${t(page3.stepsTitle)}</h2>${stepList(context, page3.steps)}</div></section>`,
    proof: () => proofSection(context),
    faq: () => faqSection(context, page3.faq),
    apply: () => `<section class="${BAND}" id="dang-ky"><div class="narrow"><div class="card form-card">${form}${identity ? `<p class="hint center mt-4">${t(identity)}</p>` : ""}</div></div></section>`
  }) + (context.open ? dock(page3.eyebrow, page3.cta, "#dang-ky") : "");
  const extraBody = `(()=>{const d=new FormData(form);return{recruit:{role:d.get('role')||'',province:d.get('province')||'',channels:d.getAll('channels'),experience:d.get('experience')||''}}})()`;
  return shell({
    type: "recruit",
    title: page3.headline,
    description: page3.introduction,
    look: context.look,
    brand: context.brand,
    settings: context.settings,
    slug: context.funnel.slug,
    preview: context.preview,
    index: true,
    bar: false,
    zalo: true,
    status: context.open ? "" : "trang \u0111ang t\u1EA1m d\u1EEBng",
    body,
    script: context.open ? `${leadFormScript("lead-form", submitUrl2(context), extraBody, "Lead")};${dockScript([".hero-cta", "#dang-ky"])}` : ""
  });
}

